shell_commands.command:
curl -N -X POST "$ALGENTA_BASE_URL/v1/simulate/stream?checkpoint_every=5000" \
-H "Authorization: Bearer $ALGENTA_API_KEY" \
-H "Content-Type: application/json" \
-d '{
"mode": "auto",
"runs": 100000,
"scenario": {
"name": "Product launch decision",
"variables": {
"revenue": { "low": 80000, "high": 200000 },
"cost":    { "low": 40000, "high": 90000 }
},
"objective": "maximize_net_value"
}
}'

curl -sS -X POST "$ALGENTA_API_URL/v1/data/connect" \
-H "Authorization: Bearer $ALGENTA_API_KEY" \
-H "Content-Type: application/json" \
-d '{
"connection_id": "'"$CONNECTOR_ID"'",
"selection": {
"sql_query": "SELECT order_id, total, region FROM sales.orders"
}
}'

curl -s -X POST "$ALGENTA_BASE_URL/v1/connectors" \
-H "Authorization: Bearer $ALGENTA_API_KEY" \
-H "Content-Type: application/json" \
-d "{
\"name\": \"Public GCS Data\",
\"connector_type\": \"gcs\",
\"config\": {
\"bucket\": \"open-datasets\",
\"blob\": \"census/2020.parquet\",
\"anonymous\": true
}
}"

curl -s -X POST "$ALGENTA_BASE_URL/v1/connectors" \
-H "Authorization: Bearer $ALGENTA_API_KEY" \
-H "Content-Type: application/json" \
-d "{
\"name\": \"App SQL Server\",
\"connector_type\": \"mssql\",
\"config\": {
\"connection_string\": \"mssql+pyodbc://reader:$MSSQL_PASSWORD@db.internal:1433/app?driver=ODBC+Driver+18+for+SQL+Server\"
}
}"

curl -s -X POST https://api.algenta.ai/v1/connectors \
-H "Authorization: Bearer $ALGENTA_API_KEY" \
-H "Content-Type: application/json" \
-d '{
"name": "analytics-warehouse",
"connector_type": "postgres",
"config": {
"connection_string": "postgresql+asyncpg://user:pass@host:5432/analytics",
"query": "SELECT * FROM revenue_by_region"
}
}'

curl -s -X POST "$ALGENTA_BASE_URL/v1/connectors" \
-H "Authorization: Bearer $ALGENTA_API_KEY" \
-H "Content-Type: application/json" \
-d "{
\"name\": \"Public Data\",
\"connector_type\": \"s3\",
\"config\": {
\"bucket\": \"open-datasets\",
\"key\": \"census/2020.parquet\",
\"region\": \"us-east-1\",
\"anonymous\": true
}
}"

curl -sS -X POST "$GATEWAY_URL/v1/decision-cases" \
-H "Authorization: Bearer $ACCESS_TOKEN" \
-H "Content-Type: application/json" \
-d '{
"pack_id": "renewal_capacity_allocation",
"title": "Q3 renewal capacity — enterprise segment",
"owner": "renewals-team@example.com",
"objective": "maximize_expected_retained_arr",
"horizon_days": 90,
"pack_input": {
"accounts": [
{"account_id": "A1", "name": "BigCo", "arr": 500000, "segment": "standard", "health_score": 42},
{"account_id": "A3", "name": "SmallStrategic", "arr": 60000, "segment": "strategic", "health_score": 55},
{"account_id": "A5", "name": "KeyStrategic", "arr": 90000, "segment": "strategic", "health_score": 70}
],
"capacity": {"total_hours": 40},
"constraints": {"strategic_min_hours": 4},
"horizon_days": 90
}
}'

curl -sS -X POST "https://api.algenta.ai/v1/repositories/$REPOSITORY_ID/pipeline" \
-H "Authorization: Bearer $ALGENTA_API_KEY" \
-H "Content-Type: application/json" \
-d '{
"snapshot_id": "'"$SNAPSHOT_ID"'",
"signals": {
"issue_text": "Refund webhook double-charges on retry",
"failing_tests": ["tests/test_refunds.py::test_idempotent_retry"]
},
"stop_after": "simulate",
"seed": 42
}'

curl -sS -X POST "$ALGENTA_API_URL/v1/repositories/$REPO_ID/triage" \
-H "Authorization: Bearer $ALGENTA_API_KEY" \
-H "Content-Type: application/json" \
-d '{
"snapshot_id": "'"$SNAPSHOT_ID"'",
"signals": {
"issue_text": "Refund webhook double-charges on retry",
"failing_tests": ["tests/test_refunds.py::test_idempotent_retry"],
"changed_files": ["src/payments/refund.py"],
"diagnostics": [
{"path": "src/payments/refund.py", "line": 88, "severity": "error", "message": "duplicate ledger write"}
]
},
"max_evidence_items": 16,
"token_budget": 6000
}'

curl -sS -X POST "https://api.algenta.ai/v1/simulate" \
-H "Authorization: Bearer $ALGENTA_API_KEY" \
-H "Content-Type: application/json" \
-d '{
"mode": "auto",
"simulation_model": "monte_carlo",
"scenario": {
"name": "Product launch decision",
"variables": {
"revenue": {"low": 80000, "high": 200000},
"cost": {"low": 40000, "high": 90000}
},
"objective": "maximize_net_value"
},
"runs": 10000,
"seed": 42
}'

curl -sS -X POST "https://api.algenta.ai/v1/triggers" \
-H "Authorization: Bearer $ALGENTA_API_KEY" \
-H "Content-Type: application/json" \
-d '{
"name": "revenue-drop",
"condition": {
"source_id": "'"$SOURCE_ID"'",
"metric_hint": "revenue",
"threshold": 100000,
"direction": "below",
"aggregation": "sum"
},
"simulation_template": {
"mode": "auto",
"scenario": {
"variables": { "revenue": { "low": 80000, "high": 200000 } },
"objective": "maximize_net_value"
},
"runs": 10000,
"seed": 42
},
"webhook_url": "https://example.com/algenta/webhook",
"description": "Re-simulate the quarter when revenue falls below target."
}'

curl -sS -X POST "$ALGENTA_API_URL/v1/chat/completions" \
-H "Authorization: Bearer $ALGENTA_API_KEY" \
-H "Content-Type: application/json" \
-d '{
"model": "provider.openai:gpt-4o",
"messages": [
{"role": "system", "content": "You are concise."},
{"role": "user", "content": "Summarize the CAP theorem in one sentence."}
]
}'
